-- Seed renamed/new A/B fields onto workspaces that already use experiment status keys.
insert into metadata_schemas (workspace_id, field_key, field_label, field_type, options, ai_fill_enabled)
select
  ms.workspace_id,
  v.field_key,
  v.field_label,
  v.field_type,
  v.options,
  v.ai_fill_enabled
from (
  select distinct workspace_id
  from metadata_schemas
  where field_key in ('experiment_status', 'ab_experiment_status')
) ms
cross join (
  values
    ('ab_experiment_status', 'Experiment status', 'status', '[{"value":"backlog","label":"Backlog","category":"unstarted"},{"value":"design","label":"Design","category":"unstarted"},{"value":"engineering","label":"Engineering","category":"started"},{"value":"live","label":"Live","category":"started"},{"value":"analyzing","label":"Analyzing","category":"started"},{"value":"concluded","label":"Concluded","category":"completed"}]'::jsonb, true),
    ('planned_duration_days', 'Planned duration', 'number', '{"unit":"days"}'::jsonb, true),
    ('traffic_split', 'Traffic split', 'text', null::jsonb, true)
) as v(field_key, field_label, field_type, options, ai_fill_enabled)
on conflict (workspace_id, field_key) do update
set
  field_label = excluded.field_label,
  field_type = excluded.field_type,
  options = excluded.options,
  ai_fill_enabled = excluded.ai_fill_enabled;

-- Refresh A/B schema groups (targeting_experiment, lift_pct) on existing workspaces.
do $migration$
declare
  ws record;
begin
  for ws in
    select distinct workspace_id
    from metadata_schemas
    where field_key in ('experiment_status', 'ab_experiment_status', 'primary_kpi_label')
  loop
    perform public.seed_scope_metadata_groups(
      ws.workspace_id,
      '[{"group_key":"targeting_experiment","group_label":"Targeting","repeatable":false,"fields":[{"sub_key":"product","field_label":"Product","field_type":"text","ai_fill_enabled":true},{"sub_key":"market","field_label":"Market","field_type":"text","ai_fill_enabled":true},{"sub_key":"audience","field_label":"Audience","field_type":"text","ai_fill_enabled":true},{"sub_key":"surface","field_label":"Surface","field_type":"text","ai_fill_enabled":true},{"sub_key":"country","field_label":"Country","field_type":"text","ai_fill_enabled":true}]},{"group_key":"ice","group_label":"ICE","repeatable":false,"fields":[{"sub_key":"impact","field_label":"Impact (1–10)","field_type":"number","ai_fill_enabled":false},{"sub_key":"confidence","field_label":"Confidence (1–10)","field_type":"number","ai_fill_enabled":false},{"sub_key":"ease","field_label":"Ease / effort (1–10)","field_type":"number","ai_fill_enabled":false}]},{"group_key":"primary_kpi","group_label":"Primary KPI","repeatable":false,"fields":[{"sub_key":"label","field_label":"Label","field_type":"text","ai_fill_enabled":true},{"sub_key":"baseline","field_label":"Baseline","field_type":"text","ai_fill_enabled":true},{"sub_key":"lift_pct","field_label":"Lift (%)","field_type":"number","options":{"unit":"%"},"ai_fill_enabled":true}]},{"group_key":"secondary_kpi","group_label":"Secondary KPI","repeatable":false,"fields":[{"sub_key":"label","field_label":"Label","field_type":"text","ai_fill_enabled":true},{"sub_key":"baseline","field_label":"Baseline","field_type":"text","ai_fill_enabled":true},{"sub_key":"lift_pct","field_label":"Lift (%)","field_type":"number","options":{"unit":"%"},"ai_fill_enabled":true}]},{"group_key":"guardrail_kpi","group_label":"Guardrail KPI","repeatable":false,"fields":[{"sub_key":"label","field_label":"Label","field_type":"text","ai_fill_enabled":true},{"sub_key":"baseline","field_label":"Baseline","field_type":"text","ai_fill_enabled":true},{"sub_key":"lift_pct","field_label":"Lift (%)","field_type":"number","options":{"unit":"%"},"ai_fill_enabled":true}]},{"group_key":"power","group_label":"Sample size & MDE","repeatable":false,"fields":[{"sub_key":"mde","field_label":"Minimum detectable effect","field_type":"text","ai_fill_enabled":true},{"sub_key":"sample_size","field_label":"Sample size (per variant)","field_type":"number","ai_fill_enabled":false},{"sub_key":"traffic_per_day","field_label":"Eligible traffic / day","field_type":"number","ai_fill_enabled":false}]},{"group_key":"primary_kpi_result","group_label":"Primary KPI result","repeatable":false,"fields":[{"sub_key":"label","field_label":"Label","field_type":"text","ai_fill_enabled":false},{"sub_key":"value","field_label":"Observed value","field_type":"text","ai_fill_enabled":false}]},{"group_key":"secondary_kpi_result","group_label":"Secondary KPI result","repeatable":false,"fields":[{"sub_key":"label","field_label":"Label","field_type":"text","ai_fill_enabled":false},{"sub_key":"value","field_label":"Observed value","field_type":"text","ai_fill_enabled":false}]},{"group_key":"guardrail_kpi_result","group_label":"Guardrail KPI result","repeatable":false,"fields":[{"sub_key":"label","field_label":"Label","field_type":"text","ai_fill_enabled":false},{"sub_key":"value","field_label":"Observed value","field_type":"text","ai_fill_enabled":false}]}]'::jsonb
    );
  end loop;
end;
$migration$;
